import { connect } from 'react-redux'
import reportingconfigActions from '../../redux/reportingConfig/actions'
import { useEffect } from 'react'
import { Button, Card, Col, Modal, notification, Row, Spin, Table } from 'antd'
import { LayoutWrapper } from './index.style'
import moment from 'moment-timezone'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import { useLocation } from 'react-router'

const ReportingConfig = ({
  getReportingList,
  reportingList,
  tableDataSourceLoading,
  tableDataSourceError,
  changeReportingConfigStatus,
  getReportingConfigStatusMessage,
  resetReportingConfigRedux,
  history
}) => {
  const location = useLocation()

  const searchParams = new URLSearchParams(location.search)
  const defaultPage = parseInt(searchParams.get('page') || '1', 10)

  useEffect(() => {
    getReportingList({ page: defaultPage || 1 })
  }, [])

  useEffect(() => {
    if (getReportingConfigStatusMessage === 'success') {
      notification.success({ message: 'Config Updated Succesfully!' })
      resetReportingConfigRedux(['getReportingConfigStatusMessage'])
      getReportingList({ page: defaultPage || 1 })
    }
  }, [getReportingConfigStatusMessage])

  const columns = [
    {
      key: 'serial',
      title: 'No',
      dataIndex: 'serial',
      render: (text, record, index) =>
        ((defaultPage || 1) - 1) * 10 + index + 1
    },
    {
      key: 'report_type',
      title: 'Report type',
      dataIndex: 'report_type',
      render: (data) => data || '-'
    },
    {
      key: 'report_name',
      title: 'Report Name',
      dataIndex: 'report_name',
      render: (data) => data || '-'
    },
    {
      key: 'report_via',
      title: 'Method',
      dataIndex: 'report_via',
      render: (data) => data || '-'
    },
    {
      key: 'send_reports_to',
      title: 'Send Reports to',
      render: (_, record) => {
        const {
          recipients_internal: recipientInternal = {},
          recipients_external: recipientExternal = {}
        } = record
        const internalEmails = Object.keys(recipientInternal)
        const externalEmails = Object.keys(recipientExternal)
        const allEmails = [...internalEmails, ...externalEmails].join(', ')
        return allEmails || '-'
      }
    },
    {
      key: 'trigger_frequency',
      title: 'Frequency',
      dataIndex: 'trigger_frequency',
      render: (data) => data || '-'
    },
    {
      key: 'created_at',
      title: 'Created At',
      dataIndex: 'created_at',
      render: (data) => (data ? moment(data).format('YYYY-MM-DD HH:mm') : '-')
    },
    {
      key: 'created_by',
      title: 'Created By',
      dataIndex: 'email',
      render: (data) => data || '-'
    },
    {
      key: 'updated_at',
      title: 'Updated At',
      dataIndex: 'updated_at',
      render: (data) => (data ? moment(data).format('YYYY-MM-DD HH:mm') : '-')
    },
    {
      key: 'last_seen',
      title: 'Last Sent',
      dataIndex: 'last_seen',
      render: (data) => data || '-'
    },
    {
      key: 'status',
      title: 'Status',
      dataIndex: 'status',
      render: (data) => data
    },
    {
      key: 'actions',
      title: 'Actions',
      render: (_, record) => (
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          <span
            className='action-button'
            onClick={() => handleRevoke(record)}
            style={{
              color: `${record.status === 'Active' ? '#FA3232' : 'green'}`
            }}
          >
            <b>{record.status === 'Active' ? 'Revoke' : 'Reinstate'}</b>
          </span>
          <span className='action-button' onClick={() => handleDetails(record)}>
            <b>Details</b>
          </span>
        </div>
      )
    }
  ]

  const handleRevoke = (record) => {
    Modal.confirm({
      title: (
        <div>
          <p>
            {`Are you sure you want to ${
              record.status === 'Active' ? 'Revoke' : 'Reinstate'
            } this reporting config?`}
          </p>
          <div>
            <b>Report Name:</b> {record.report_name}
          </div>
          <div>
            <b>Current Status:</b> {record.status}
          </div>
        </div>
      ),
      okText: 'OK',
      cancelText: 'Cancel',
      onOk: () => {
        changeReportingConfigStatus({
          report_id: record.id,
          status: record.status !== 'Active'
        })
      }
    })
  }

  const handleDetails = (record) => {
    const reportId = record.id
    history.push(`/reporting-config/details/${reportId}`)
  }

  const handleAddConfig = () => {
    history.push('/reporting-config/add-config')
  }

  const handlePageChange = (val) => {
    const { current } = val
    const searchText = {}
    searchText.page = current
    const search = QuerySearchBuilder(searchText)
    history.push({ pathname: location.pathname, search })
    getReportingList({ page: current })
  }

  return (
    <LayoutWrapper>
      <Card>
        <Row type='flex' justify='space-between'>
          <Col>
            <h1 className='label-name'>
              <b>Reporting Config List:</b>
            </h1>
          </Col>
          <Col>
            <div className='button__section'>
              <Button type='primary' onClick={handleAddConfig}>
                Add Report Template
              </Button>
            </div>
          </Col>
        </Row>
        <div className='table-container'>
          <Spin
            spinning={tableDataSourceLoading && !tableDataSourceError}
            tip='Reportig List Loading ...'
          >
            <Table
              bordered
              columns={columns}
              dataSource={reportingList.results}
              rowKey={(record) => record.id}
              pagination={{
                pageSize: 10,
                defaultCurrent: defaultPage || 1,
                total: reportingList.count
              }}
              onChange={handlePageChange}
              scroll={{ x: 'max-content' }}
            />
          </Spin>
        </div>
      </Card>
    </LayoutWrapper>
  )
}

export default connect(
  (state) => ({
    reportingList: state.ReportingConfigurable.reportingList,
    tableDataSourceMessage: state.ReportingConfigurable.reportingListMessage,
    tableDataSourceLoading: state.Loading.GET_REPORTING_LIST,
    getReportingConfigStatusMessage:
      state.ReportingConfigurable.getReportingConfigStatusMessage
  }),
  {
    getReportingList: reportingconfigActions.getReportingList,
    changeReportingConfigStatus:
      reportingconfigActions.changeReportingConfigStatus,
    resetReportingConfigRedux: reportingconfigActions.resetReportingConfigRedux
  }
)(ReportingConfig)
